//! Database engine identity for this project.
//!
//! The ONLY database engine is real C SQLite, built from SQLite's
//! `begin-concurrent` branch (plain WAL mode, `BEGIN CONCURRENT`):
//!
//! * `libsqlite3-sys` is `[patch.crates-io]`-redirected to the in-repo
//!   copy under `vendor/libsqlite3-sys`, whose bundled amalgamation is
//!   generated by `scripts/sqlite-amalgamate.sh`; the exact commit is
//!   recorded in `vendor/libsqlite3-sys/PINNED`.
//! * sea-orm (via sqlx-sqlite) compiles and statically links that
//!   amalgamation into the binary — no `libsqlite3.so`, no system
//!   SQLite, no postgres backend.
//! * [`pool`] builds the connection pool: SQLite pragmas are
//!   per-connection, so they are set as connect options and every pooled
//!   connection gets them.
//! * [`write`] runs multi-statement write transactions as
//!   `BEGIN CONCURRENT`, retrying the whole transaction on conflict.
//! * [`checkpoint`] keeps the WAL file small (periodic checkpoints).

pub mod checkpoint;
pub mod pool;
pub mod write;

use std::ffi::CStr;

/// `sqlite3_libversion()` of the linked engine (e.g. `3.55.0`).
pub fn sqlite_version() -> &'static str {
    // SAFETY: sqlite3_libversion() returns a pointer to a string literal
    // compiled into the library — never null, valid for the life of the
    // process and never mutated.
    static_ascii(unsafe { libsqlite3_sys::sqlite3_libversion() })
}

/// `sqlite3_sourceid()` of the linked engine: the SQLite check-in
/// timestamp + hash, which must equal the `source_id` in
/// `vendor/libsqlite3-sys/PINNED`.
pub fn sqlite_source_id() -> &'static str {
    // SAFETY: as for `sqlite_version` — a static string literal.
    static_ascii(unsafe { libsqlite3_sys::sqlite3_sourceid() })
}

/// View one of SQLite's static, NUL-terminated ASCII identity strings.
fn static_ascii(ptr: *const std::os::raw::c_char) -> &'static str {
    // SAFETY: callers pass a non-null pointer to a static C string.
    unsafe { CStr::from_ptr(ptr) }.to_str().unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use sea_orm::{ConnectionTrait, Database, DatabaseConnection, DbBackend, Statement};

    /// The `vendor/libsqlite3-sys/PINNED` file, embedded at build time.
    const PINNED: &str = include_str!("../../vendor/libsqlite3-sys/PINNED");

    fn pinned(key: &str) -> &'static str {
        PINNED
            .lines()
            .find_map(|line| line.strip_prefix(key)?.strip_prefix('='))
            .unwrap_or_else(|| panic!("PINNED has no `{key}` line"))
    }

    /// One-connection pool on a fresh WAL database file (BEGIN CONCURRENT
    /// needs WAL; `:memory:` databases cannot use it).
    async fn wal_file_db(dir: &tempfile::TempDir) -> DatabaseConnection {
        let url = format!("sqlite://{}?mode=rwc", dir.path().join("t.db").display());
        let mut opts = sea_orm::ConnectOptions::new(url);
        opts.max_connections(1).sqlx_logging(false);
        let db = Database::connect(opts).await.expect("connect");
        db.execute_unprepared("PRAGMA journal_mode = WAL")
            .await
            .expect("enable WAL");
        db
    }

    #[test]
    fn linked_sqlite_matches_the_pinned_amalgamation() {
        assert_eq!(super::sqlite_source_id(), pinned("source_id"));
        assert_eq!(super::sqlite_version(), pinned("version"));
    }

    #[tokio::test]
    async fn compile_options_include_fts5() {
        let db = Database::connect("sqlite::memory:").await.expect("connect");
        let rows = db
            .query_all(Statement::from_string(
                DbBackend::Sqlite,
                "PRAGMA compile_options",
            ))
            .await
            .expect("compile_options");
        let options: Vec<String> = rows
            .iter()
            .map(|r| r.try_get_by_index(0).expect("option text"))
            .collect();
        for wanted in [
            "ENABLE_FTS5",
            "DQS=0",
            "ENABLE_MATH_FUNCTIONS",
            "DEFAULT_WAL_SYNCHRONOUS=1",
        ] {
            assert!(
                options.iter().any(|o| o == wanted),
                "missing {wanted} in {options:?}"
            );
        }
        assert!(
            !options.iter().any(|o| o == "OMIT_CONCURRENT"),
            "BEGIN CONCURRENT is compiled out: {options:?}"
        );
    }

    #[tokio::test]
    async fn begin_concurrent_is_accepted_in_wal_mode() {
        let dir = tempfile::tempdir().expect("tempdir");
        let db = wal_file_db(&dir).await;
        db.execute_unprepared("CREATE TABLE t (id INTEGER PRIMARY KEY)")
            .await
            .expect("create");
        db.execute_unprepared("BEGIN CONCURRENT")
            .await
            .expect("BEGIN CONCURRENT accepted");
        db.execute_unprepared("INSERT INTO t (id) VALUES (1)")
            .await
            .expect("insert in concurrent tx");
        db.execute_unprepared("COMMIT").await.expect("commit");
    }
}
